CREATE TABLE IF NOT EXISTS mdd_templates (template_id TEXT PRIMARY KEY, template_family TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_template_versions (template_version_id TEXT PRIMARY KEY, template_id TEXT NOT NULL, version_number TEXT NOT NULL, effective_date TEXT, retired_at TEXT, created_by_user_id TEXT, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(template_id) REFERENCES mdd_templates(template_id));
CREATE TABLE IF NOT EXISTS mdd_template_sections (template_section_id TEXT PRIMARY KEY, template_version_id TEXT NOT NULL, section_id TEXT NOT NULL, section_number TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 1, conditional_rule_json TEXT NOT NULL DEFAULT '{}', metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_documents (mdd_document_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, template_version_id TEXT, current_validated_version_id TEXT, created_by_user_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_document_versions (mdd_document_version_id TEXT PRIMARY KEY, mdd_document_id TEXT NOT NULL, version_number TEXT NOT NULL, status TEXT NOT NULL, prior_validated_version_id TEXT, summary_of_changes TEXT, created_by_user_id TEXT, created_at TEXT NOT NULL, submitted_at TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_sections (mdd_section_id TEXT PRIMARY KEY, mdd_document_version_id TEXT NOT NULL, section_id TEXT NOT NULL, section_number TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'working_draft', not_applicable_rationale TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_content_blocks (block_id TEXT PRIMARY KEY, mdd_section_id TEXT NOT NULL, block_type TEXT NOT NULL, title TEXT, content_json TEXT NOT NULL DEFAULT '{}', source_type TEXT NOT NULL, source_reference_json TEXT NOT NULL DEFAULT '{}', generated_indicator TEXT NOT NULL DEFAULT 'human_authored', review_status TEXT NOT NULL DEFAULT 'draft', created_by_user_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_change_records (change_record_id TEXT PRIMARY KEY, mdd_document_version_id TEXT NOT NULL, section_id TEXT NOT NULL, prior_text_hash TEXT, new_text_hash TEXT, change_type TEXT NOT NULL, reason TEXT, linked_reference_json TEXT NOT NULL DEFAULT '{}', author_user_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mdd_version_control_entries (version_control_entry_id TEXT PRIMARY KEY, mdd_document_version_id TEXT NOT NULL, summary TEXT NOT NULL, changed_sections_json TEXT NOT NULL DEFAULT '[]', change_classification TEXT, author_user_id TEXT, approval_status TEXT NOT NULL DEFAULT 'working_draft', created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_evidence_links (mdd_evidence_link_id TEXT PRIMARY KEY, mdd_section_id TEXT NOT NULL, evidence_reference_json TEXT NOT NULL DEFAULT '{}', canonical_version_reference TEXT, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS mdd_completeness_results (mdd_completeness_result_id TEXT PRIMARY KEY, mdd_document_version_id TEXT NOT NULL, completion_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mdd_documents_project ON mdd_documents(project_id);
CREATE INDEX IF NOT EXISTS idx_mdd_versions_document ON mdd_document_versions(mdd_document_id, status);
CREATE INDEX IF NOT EXISTS idx_mdd_sections_version ON mdd_sections(mdd_document_version_id);
CREATE INDEX IF NOT EXISTS idx_mdd_changes_version ON mdd_change_records(mdd_document_version_id);
